  int countCategory(String cat){List<Channel> b=baseForCategory(cat);return b==null?0:b.size();}
  void addIndex(Map<String,List<Channel>> map,String key,Channel ch){List<Channel> x=map.get(key);if(x==null){x=new ArrayList<>();map.put(key,x);}x.add(ch);}
  String canonicalCategory(Channel ch){String raw=ch.group==null?"":ch.group.trim(),clean=cleanGroup(raw).toLowerCase(Locale.ROOT);if(raw.startsWith("01 ")||clean.contains("deport")||clean.contains("sport"))return "Deportes";if(raw.startsWith("02 ")||clean.contains("cine"))return "Cine en vivo";if(raw.startsWith("03 ")||clean.contains("serie"))return "Series en vivo";if(raw.startsWith("04 ")||clean.contains("crist")||clean.contains("relig"))return "Religiosos";if(raw.startsWith("05 ")||clean.contains("noticia")||clean.contains("news"))return "Noticias";if(raw.startsWith("06 ")||clean.contains("infantil")||clean.contains("kids"))return "Infantiles";if(raw.startsWith("07 ")||clean.contains("música")||clean.contains("musica")||clean.contains("music"))return "Música";if(raw.startsWith("08 ")||clean.contains("document")||clean.contains("cultura"))return "Documentales";if(raw.startsWith("09 ")||clean.contains("entreten"))return "Entretenimiento";return "Otros";}
  void rebuildChannelIndex(){categoryIndex.clear();countryIndex.clear();for(Channel ch:all){addIndex(categoryIndex,canonicalCategory(ch),ch);String raw=ch.group==null?"":ch.group.trim();if(raw.startsWith("20 "))addIndex(countryIndex,cleanGroup(raw),ch);}}
  List<Channel> baseForCategory(String cat){if(cat==null||"Todos".equals(cat))return all;if(cat.startsWith("País:")){List<Channel> x=countryIndex.get(cat.substring(5));return x==null?Collections.emptyList():x;}List<Channel> x=categoryIndex.get(cat);return x==null?Collections.emptyList():x;}
