  void attachMainPlayer(){if(playerView==null){playerView=new PlayerView(this);playerView.setUseController(true);playerView.setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING);playerView.setFocusable(true);}applyResizeMode(playerView);ViewParent p=playerView.getParent();if(p instanceof ViewGroup)((ViewGroup)p).removeView(playerView);if(homePlayerHolder!=null){homePlayerHolder.addView(playerView,0,new FrameLayout.LayoutParams(-1,-1));if(player!=null)playerView.setPlayer(player);}}

  void initPlayer(){player=new ExoPlayer.Builder(this).build();player.addListener(new Player.Listener(){
    @Override public void onPlaybackStateChanged(int s){
      if(s==Player.STATE_READY){cancelStartupWatchdog();retries=0;setLiveStatus("En vivo"+channelPositionText(),CYAN);}
      else if(s==Player.STATE_BUFFERING)setLiveStatus(retries>0?"Reconectando "+retries+"/3…":"Cargando señal…",CYAN);
      else if(s==Player.STATE_ENDED)setLiveStatus("Transmisión finalizada",ORANGE);
    }
    @Override public void onIsPlayingChanged(boolean playing){if(playing&&player.getPlaybackState()==Player.STATE_READY)setLiveStatus("En vivo"+channelPositionText(),CYAN);}
    @Override public void onPlayerError(PlaybackException e){cancelStartupWatchdog();setLiveStatus(errorLabel(e),ORANGE);if(autoRetryEnabled)autoRetry();}
  });attachMainPlayer();}

  void bindList(){adapter=new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,new ArrayList<String>()){@Override public View getView(int p,View c,ViewGroup parent){TextView v=(TextView)super.getView(p,c,parent);v.setTextColor(Color.WHITE);v.setTextSize(13);v.setPadding(dp(12),dp(5),dp(8),dp(5));v.setMinHeight(dp(50));boolean active=p<shown.size()&&current!=null&&shown.get(p).id.equals(current.id);v.setBackground(rounded(active?PV_PRIMARY:Color.argb(225,6,29,50),12));return v;}};channelList.setAdapter(adapter);channelList.setOnItemClickListener((p,v,pos,id)->play(shown.get(pos)));channelList.setOnItemLongClickListener((p,v,pos,id)->{Channel ch=shown.get(pos);toggleFavorite(ch);filter();toast(favorites.contains(ch.id)?"Añadido a favoritos":"Eliminado de favoritos");return true;});search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){if(searchFilterTask!=null)mainHandler.removeCallbacks(searchFilterTask);searchFilterTask=MainActivity.this::filter;mainHandler.postDelayed(searchFilterTask,180);}public void afterTextChanged(android.text.Editable e){}});}

  String cleanGroup(String raw){if(raw==null)return "Otros";String s=raw.trim().replaceFirst("^\\d+\\s+","").replaceFirst("^[^\\p{L}\\p{N}]+","").trim();return s.isEmpty()?"Otros":s;}
  String displayCategory(String cat){return cat!=null&&cat.startsWith("País:")?cat.substring(5):cat;}
  boolean categoryMatch(Channel c,String cat){if(cat==null||cat.equals("Todos"))return true;String raw=c.group==null?"":c.group.trim();String clean=cleanGroup(raw);if(cat.startsWith("País:"))return raw.startsWith("20 ")&&clean.equalsIgnoreCase(cat.substring(5));if(cat.equals("Deportes"))return raw.startsWith("01 ")||clean.equalsIgnoreCase("Deportes");if(cat.equals("Cine en vivo"))return raw.startsWith("02 ")||clean.equalsIgnoreCase("Cine en vivo");if(cat.equals("Series en vivo"))return raw.startsWith("03 ")||clean.equalsIgnoreCase("Series en vivo");if(cat.equals("Religiosos"))return raw.startsWith("04 ")||clean.toLowerCase(Locale.ROOT).contains("cristian");if(cat.equals("Noticias"))return raw.startsWith("05 ")||clean.equalsIgnoreCase("Noticias");if(cat.equals("Infantiles"))return raw.startsWith("06 ")||clean.toLowerCase(Locale.ROOT).contains("infantil");if(cat.equals("Música"))return raw.startsWith("07 ")||clean.equalsIgnoreCase("Música");if(cat.equals("Documentales"))return raw.startsWith("08 ")||clean.toLowerCase(Locale.ROOT).contains("document");if(cat.equals("Entretenimiento"))return raw.startsWith("09 ")||clean.equalsIgnoreCase("Entretenimiento");return clean.equalsIgnoreCase(cat);}
  boolean has(String x,String...keys){for(String k:keys)if(x.contains(k))return true;return false;}

  void filter(){if(adapter==null||search==null)return;String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);shown.clear();Set<String> recentSet=new HashSet<>(recents);List<Channel> base=baseForCategory(category);for(Channel c:base){boolean mm=mode.equals("all")||(mode.equals("fav")&&favorites.contains(c.id))||(mode.equals("recent")&&recentSet.contains(c.id));if(mm&&(q.isEmpty()||c.search.contains(q)))shown.add(c);}if(mode.equals("recent")){final Map<String,Integer> rank=new HashMap<>();int i=0;for(String id:recents)rank.put(id,i++);Collections.sort(shown,(a,b)->Integer.compare(rank.containsKey(a.id)?rank.get(a.id):9999,rank.containsKey(b.id)?rank.get(b.id):9999));}List<String> names=new ArrayList<>(shown.size());for(Channel c:shown)names.add(c.name+"\n"+cleanGroup(c.group));adapter.clear();adapter.addAll(names);adapter.notifyDataSetChanged();count.setText(category.equals("Todos")?shown.size()+" canales":shown.size()+" canales · "+displayCategory(category));}

  void play(Channel c){if(c==null)return;if(!networkConnected()){setLiveStatus("Sin conexión de red",ORANGE);return;}if(current!=null&&!current.id.equals(c.id))previous=current;current=c;retries=0;addRecent(c.id);if(title!=null)title.setText(c.name+"  ·  "+cleanGroup(c.group));setLiveStatus("Conectando…",CYAN);if(playerEmpty!=null)playerEmpty.setVisibility(View.GONE);updateFav();startCurrentStream();filter();}
  void startCurrentStream(){if(current==null)return;playToken++;connectStartedAt=SystemClock.elapsedRealtime();player.setMediaItem(new MediaItem.Builder().setUri(current.url).setMediaId(current.id).build());player.prepare();player.play();armStartupWatchdog(playToken);}
  void restart(){if(current==null)return;if(!networkConnected()){setLiveStatus("Sin conexión de red · toca Reconectar",ORANGE);return;}setLiveStatus(retries>0?"Reconectando "+retries+"/3…":"Reconectando…",CYAN);startCurrentStream();}
  void autoRetry(){if(current==null)return;if(retries<3){retries++;setLiveStatus("Reconectando "+retries+"/3…",CYAN);mainHandler.postDelayed(this::restart,700L+retries*700L);}else setLiveStatus("Canal sin respuesta · prueba Verificar",ORANGE);}
  void step(int d){List<Channel> base=!shown.isEmpty()&&current!=null&&shown.contains(current)?shown:all;if(base.isEmpty())return;int i=current==null?-1:base.indexOf(current);if(i<0)i=0;else i=(i+d+base.size())%base.size();play(base.get(i));}
  void toggleFavorite(){toggleFavorite(current);}
  void toggleFavorite(Channel c){if(c==null)return;if(!favorites.add(c.id))favorites.remove(c.id);savePrefs();updateFav();}
  void updateFav(){if(favButton!=null){boolean on=current!=null&&favorites.contains(current.id);favButton.setText(on?"Guardado":"Favorito");favButton.setBackground(buttonBg(on?PV_PRIMARY:PV_BUTTON,on?Color.rgb(20,132,255):PV_BUTTON_FOCUS,14));setButtonIcon(favButton,R.drawable.pv_ic_star,true);}}
  void addRecent(String id){recents.remove(id);recents.addFirst(id);while(recents.size()>30)recents.removeLast();savePrefs();}

  void showMoreMenu(){LinearLayout p=pageBase("Opciones del reproductor","Controles del canal actual");Button full=menuCard("Pantalla completa","Aprovecha toda la pantalla",R.drawable.pv_ic_fullscreen),fit=menuCard("Ajuste de imagen · "+resizeModeName(),"Ajustar, llenar, estirar u original",R.drawable.pv_ic_crop),check=menuCard("Verificar canal","Comprueba si el enlace actual responde",R.drawable.pv_ic_info),audio=menuCard("Audio","Selecciona la pista de audio",R.drawable.pv_ic_audio),subs=menuCard("Subtítulos","Activa o cambia subtítulos",R.drawable.pv_ic_subtitles);for(Button b:new Button[]{full,fit,check,audio,subs}){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(62));lp.setMargins(dp(4),dp(4),dp(4),dp(4));p.addView(b,lp);}full.setOnClickListener(v->openFullscreen());fit.setOnClickListener(v->{cycleResizeMode();showMoreMenu();});check.setOnClickListener(v->validateCurrent());audio.setOnClickListener(v->showTracks(C.TRACK_TYPE_AUDIO));subs.setOnClickListener(v->showTracks(C.TRACK_TYPE_TEXT));}

  void showTracks(int type){if(current==null){toast("Seleccione un canal primero");return;}Tracks t=player.getCurrentTracks();final List<TrackSelectionOverride> ovs=new ArrayList<>();final List<String> labels=new ArrayList<>();if(type==C.TRACK_TYPE_TEXT)labels.add("Desactivados");for(Tracks.Group g:t.getGroups()){if(g.getType()!=type)continue;for(int i=0;i<g.length;i++){Format f=g.getTrackFormat(i);String l=f.label!=null?f.label:(f.language!=null?f.language:(type==C.TRACK_TYPE_AUDIO?"Audio ":"Subtítulo ")+(labels.size()+1));labels.add(l);ovs.add(new TrackSelectionOverride(g.getMediaTrackGroup(),i));}}if(labels.isEmpty()||(type==C.TRACK_TYPE_TEXT&&labels.size()==1)){toast(type==C.TRACK_TYPE_AUDIO?"No hay pistas de audio adicionales":"Este canal no ofrece subtítulos");return;}AlertDialog td=new AlertDialog.Builder(this).setTitle(type==C.TRACK_TYPE_AUDIO?"Audio":"Subtítulos").setItems(labels.toArray(new String[0]),(d,w)->{TrackSelectionParameters.Builder b=player.getTrackSelectionParameters().buildUpon();if(type==C.TRACK_TYPE_TEXT&&w==0)b.setTrackTypeDisabled(C.TRACK_TYPE_TEXT,true);else{int x=type==C.TRACK_TYPE_TEXT?w-1:w;b.setTrackTypeDisabled(type,false);b.setOverrideForType(ovs.get(x));}player.setTrackSelectionParameters(b.build());}).create();styleDialog(td);}

